    // According to the problem statement:
    // - input[0] and input[2] are each 'H' or 'D'.
    // - We return ['H', '\n'] if they are equal, otherwise ['D', '\n'].
    let output_char = if input[0] == input[2] { 'H' } else { 'D' };
